/* ---------- cinematic title backdrop scene ---------- */
function buildTitleScene(){
  const scene = newScene({bg:'#06080f', fog:'#08101e'});
  scene.fog.near = 18; scene.fog.far = 80;

  scene.add(new THREE.AmbientLight('#3a4878', 0.5));
  const sun = addSun(scene, '#ff8050', 0.7, new THREE.Vector3(-8, 4, 6));
  // warm rim from the city
  const rim = new THREE.PointLight('#ff6a30', 1.2, 50);
  rim.position.set(0, 4, -25); scene.add(rim);

  // stylized Lagos skyline silhouette — rows of buildings at varying heights
  const city = new THREE.Group();
  for(let i=0;i<24;i++){
    const x = -28 + i*2.4 + (Math.random()-.5)*0.6;
    const h = 4 + Math.random()*9;
    const w = 1.6 + Math.random()*0.8;
    const d = 1.6 + Math.random()*0.8;
    const z = -16 - Math.random()*4;
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), toonMat('#0a1428'));
    b.position.set(x, h/2, z); b.castShadow=true; city.add(b); outline(b,1.04);
    // window grid — emissive
    const cnv = document.createElement('canvas'); cnv.width=32; cnv.height=64;
    const cx = cnv.getContext('2d');
    cx.fillStyle = '#0a1428'; cx.fillRect(0,0,32,64);
    for(let r=0;r<10;r++) for(let c=0;c<4;c++){
      cx.fillStyle = Math.random()<0.55 ? `rgba(${220+Math.random()*30},${170+Math.random()*40},${90+Math.random()*40},${0.6+Math.random()*0.4})` : 'rgba(0,0,0,0)';
      cx.fillRect(2 + c*7, 4 + r*5.5, 4, 2.5);
    }
    const tex = new THREE.CanvasTexture(cnv);
    const winFront = new THREE.Mesh(new THREE.PlaneGeometry(w*0.92, h*0.92), new THREE.MeshBasicMaterial({map:tex, transparent:true}));
    winFront.position.set(x, h/2, z + d/2 + 0.01); city.add(winFront);
  }
  // a closer mid-ground building (Third Mainland Bridge feel)
  for(let i=0;i<8;i++){
    const x = -10 + i*3 + (Math.random()-.5)*0.4;
    const h = 6 + Math.random()*4;
    const b = new THREE.Mesh(new THREE.BoxGeometry(2, h, 2), toonMat('#0a0e1a'));
    b.position.set(x, h/2, -8 - Math.random()*2); city.add(b); outline(b,1.04);
  }
  scene.add(city);

  // ground (faint reflection)
  addTexturedGround(scene, asphaltTexture(), 80, '#1a1d22');

  // moonlight god ray over the skyline
  addGodRay(scene, -2, 14, -16, 6, 0, 16, '#a8c0ff', 0.18, 0.1);
  addGodRay(scene, 6, 12, -14, 4, 0, 14, '#ffb070', 0.14, -0.05);

  // dust/embers
  addDustMotes(scene, 200, 60, 12, 30, '#ffd58a');

  // floating NACECA shield — uses the rendered badge image if available
  const shield = new THREE.Group();
  if(typeof ASSETS !== 'undefined' && ASSETS.title && ASSETS.title.naceca_badge){
    // Textured plane with the rendered badge
    const tex = new THREE.TextureLoader().load(ASSETS.title.naceca_badge);
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    const badgePlane = new THREE.Mesh(
      new THREE.PlaneGeometry(4.4, 5.5),
      new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false })
    );
    shield.add(badgePlane);
    // bigger, softer halo glow behind the badge
    const glow = new THREE.Mesh(new THREE.CircleGeometry(4.4, 32), new THREE.MeshBasicMaterial({
      color: 0xf0c878, transparent:true, opacity:0.35, blending:THREE.AdditiveBlending, depthWrite:false
    }));
    glow.position.z = -0.2; shield.add(glow);
    // a second outer ember halo
    const halo2 = new THREE.Mesh(new THREE.CircleGeometry(6.5, 32), new THREE.MeshBasicMaterial({
      color: 0xff8050, transparent:true, opacity:0.12, blending:THREE.AdditiveBlending, depthWrite:false
    }));
    halo2.position.z = -0.4; shield.add(halo2);
  } else {
    // Fallback — procedural hex shield (original)
    const sh1 = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.6, 0.3, 6), toonMat('#0b1426'));
    sh1.rotation.z = Math.PI/2; sh1.rotation.x = Math.PI/2; shield.add(sh1); outline(sh1,1.05);
    const sh2 = new THREE.Mesh(new THREE.CylinderGeometry(1.9, 2.3, 0.32, 6), toonMat('#d8a64a'));
    sh2.rotation.z = Math.PI/2; sh2.rotation.x = Math.PI/2; sh2.position.z = 0.05; shield.add(sh2);
    const glow = new THREE.Mesh(new THREE.CircleGeometry(3.0, 24), new THREE.MeshBasicMaterial({
      color: 0xd8a64a, transparent:true, opacity:0.25, blending:THREE.AdditiveBlending, depthWrite:false
    }));
    glow.position.z = -0.5; shield.add(glow);
  }
  shield.position.set(0, 6, -3);
  shield.userData._title = true;
  scene.add(shield);

  // camera position — slow cinematic slow-pan
  ENGINE.camera.position.set(-3, 5, 10);
  ENGINE.camera.lookAt(0, 5, -5);
  ENGINE._titleCam = { t:0, baseY:5 };
}
function updateTitleCam(dt){
  if(!ENGINE._titleCam || !ENGINE.scene) return;
  ENGINE._titleCam.t += dt;
  const t = ENGINE._titleCam.t;
  // slow drift
  ENGINE.camera.position.x = Math.sin(t*0.08) * 4;
  ENGINE.camera.position.y = 5 + Math.sin(t*0.05) * 0.6;
  ENGINE.camera.position.z = 10 + Math.cos(t*0.07) * 1.5;
  ENGINE.camera.lookAt(0, 5, -5);
  // rotate the shield
  ENGINE.scene.traverse(obj=>{
    if(obj.userData && obj.userData._title){
      obj.rotation.y = Math.sin(t*0.4) * 0.25;
      obj.position.y = 6 + Math.sin(t*0.6) * 0.2;
    }
  });
}

window.addEventListener('load', ()=>{
  bindDialogueTap();
  initThree();
  startArtLoad();
  loadSettings();
  bindInput();
  ensureHudV8();
  bindMenuButtons();
  bindExtraMenus();
  // build the cinematic title backdrop scene
  buildTitleScene();
  showOverlay('screen-title');
  $('#btn-continue').disabled = !hasSave();
  // start title ambient pad after first user interaction
  document.addEventListener('pointerdown', ()=>{ initAudio(); startAmbient('title'); musicForScene('title'); }, {once:true});
  tick();
});

/* Settings + Case Records buttons on the title and pause screens */
function bindExtraMenus(){
  const add = (sel, id, label, fn)=>{
    const host = document.querySelector(sel); if(!host || document.getElementById(id)) return;
    const b = document.createElement('button'); b.className = 'btn ghost'; b.id = id; b.textContent = label;
    b.addEventListener('click', fn); host.appendChild(b);
  };
  add('#screen-title .title-actions', 'btn-title-settings', 'SETTINGS', openSettings);
  add('#screen-title .title-actions', 'btn-title-records', 'CASE RECORDS', openRecords);
  add('#screen-pause .title-actions', 'btn-pause-settings', 'SETTINGS', openSettings);
  add('#screen-pause .title-actions', 'btn-pause-records', 'CASE RECORDS', openRecords);
}


/* ---------- systems/art_pass_v8.js ---------- */
/* ---------------- third-person camera ----------------
   Slightly above and behind Kelechi with a shoulder offset so the view ahead
   stays clear. Smooth follow, wall collision (snaps in, eases out), a gentle
   re-centre behind him while he moves, and an override used to frame
   interactions. Wider lens in portrait so phones see the room. */
const TPCAM = { pos:null, look:null, dist:3.5, height:0.0, lookH:1.45, shoulder:0.38, override:null, solids:null, solidsScene:null, cur:null, fov:55 };
function setCameraSolids(list){ TPCAM.solids = list; TPCAM.solidsScene = ENGINE.scene; }
function updateCamera(){
  if(!ENGINE.player || !ENGINE.camera) return;
  if(!ENGINE.player.userData._skinned) return updateCameraLegacy();
  const cam = ENGINE.camera, p = ENGINE.player.position;
  const dt = Math.min(0.05, ENGINE._dt || 0.016);
  if(!TPCAM.pos){ TPCAM.pos = new THREE.Vector3(); TPCAM.look = new THREE.Vector3(); TPCAM._ray = new THREE.Raycaster(); TPCAM._v = new THREE.Vector3(); TPCAM._d = new THREE.Vector3(); TPCAM._piv = new THREE.Vector3(); }
  // auto re-centre behind the player while moving (not while the player is steering the camera)
  const sinceDrag = performance.now() - (ENGINE._lastCamDrag || 0);
  const moving = (ENGINE.player.userData._speed || 0) > 0.5;
  if(moving && sinceDrag > 1400 && !ENGINE.seq){
    let d = ENGINE.playerYaw - ENGINE.cameraYaw; while(d > Math.PI) d -= Math.PI*2; while(d < -Math.PI) d += Math.PI*2;
    if(Math.abs(d) < 2.4) ENGINE.cameraYaw += d * Math.min(1, dt*1.1);
  }
  const yaw = ENGINE.cameraYaw, pitch = Math.max(-0.05, Math.min(0.95, ENGINE.playerPitch));
  const fx = Math.sin(yaw), fz = Math.cos(yaw);          // view direction on the ground
  const rx = -Math.cos(yaw), rz = Math.sin(yaw);         // screen-right
  const portrait = innerHeight > innerWidth;
  const dist = TPCAM.dist * (portrait ? 1.08 : 1);
  const sh = TPCAM.shoulder * (portrait ? 0.55 : 1);
  const piv = TPCAM._piv.set(p.x + rx*sh, p.y + TPCAM.lookH, p.z + rz*sh);
  let want = TPCAM._v.set(piv.x - fx*Math.cos(pitch)*dist, piv.y + Math.sin(pitch)*dist + 0.25, piv.z - fz*Math.cos(pitch)*dist);
  // collision: pull in front of walls. The mansion registers its own blockers;
  // older scenes use the solid boxes gathered by the legacy camera.
  let solids = null;
  if(TPCAM.solids && TPCAM.solidsScene === ENGINE.scene) solids = TPCAM.solids;
  else if(typeof gatherCameraSolids === 'function'){ if(_camRay.scene !== ENGINE.scene) gatherCameraSolids(); solids = _camRay.solids; }
  if(solids && solids.length){
    // three rays (centre + either side) act like a fat probe so door frames don't clip the lens
    const dir = TPCAM._d.copy(want).sub(piv); const L = dir.length(); dir.normalize();
    let best = L + 0.3; const o = TPCAM._o || (TPCAM._o = new THREE.Vector3());
    for(const off of [0, -0.3, 0.3]){
      o.set(piv.x + rx*off, piv.y, piv.z + rz*off);
      TPCAM._ray.set(o, dir); TPCAM._ray.far = L + 0.3;
      const hit = TPCAM._ray.intersectObjects(solids, false)[0];
      if(hit && hit.distance < best) best = hit.distance;
    }
    if(best < L + 0.3){
      const k = Math.max(0.55, best - 0.32);
      want = TPCAM._v.copy(piv).addScaledVector(dir, k);
      want.y += (L - k) * 0.55;                    // rise over the obstacle instead of staring into it
    }
  }
  if(ENGINE.ceilingY !== undefined && ENGINE.inside && ENGINE.inside(p)) want.y = Math.min(want.y, ENGINE.ceilingY - 0.18);
  let lookAt = TPCAM._look2 || (TPCAM._look2 = new THREE.Vector3());
  lookAt.set(piv.x + fx*1.6, p.y + TPCAM.lookH - 0.15 + Math.sin(pitch)*0.2, piv.z + fz*1.6);
  if(TPCAM.override){ want = TPCAM.override.pos; lookAt = TPCAM.override.look; }
  // smoothing: snap in quickly when the wall pushes us, ease everywhere else
  if(!TPCAM.cur){ TPCAM.pos.copy(want); TPCAM.look.copy(lookAt); TPCAM.cur = true; }
  const k = 1 - Math.exp(-dt * (TPCAM.override ? 5 : 10));
  TPCAM.pos.lerp(want, k); TPCAM.look.lerp(lookAt, 1 - Math.exp(-dt * (TPCAM.override ? 5 : 14)));
  cam.position.copy(TPCAM.pos); cam.lookAt(TPCAM.look);
  const fov = portrait ? 68 : 55;
  if(Math.abs(cam.fov - fov) > 0.1){ cam.fov += (fov - cam.fov) * Math.min(1, dt*6); cam.updateProjectionMatrix(); }
  if(typeof applyShake==='function') applyShake();
}
function resetCameraFollow(){ TPCAM.cur = null; TPCAM.override = null; }


