      x.fillStyle='#1a4aa0'; x.fillRect(512,256,512,128); txt(x,'RECHARGE CARD · POS',768,312,font(40),'#ffffff'); txt(x,'COLD DRINKS · BREAD · INDOMIE',768,360,font(26,'600'),'#ffd040');
      // F: house number, G: street sign
